// Paper colours for a native shell. Generated by scripts/generate.mjs from the files in tokens/. Do not edit.
//
// Each colour is a 24-bit sRGB value, 0xRRGGBB. A shell can paint its window and
// title bar with Light.topbar or Dark.topbar so that nothing flashes a different
// colour before the page loads. Plain Swift with no imports.

public enum PaperTokens {
    public enum Light {
        /// Page background
        public static let bg: UInt32 = 0xF7F7F8
        /// Panels and the primary reading surface
        public static let surface: UInt32 = 0xFFFFFF
        /// Recessed fills such as segmented tracks and hovered rows
        public static let surface2: UInt32 = 0xF1F2F4
        /// Deepest fill
        public static let surface3: UInt32 = 0xE8EAED
        /// The selected item of a segmented control or segmented tabs, on a surface-2 track. Components read this token instead of testing the mode.
        public static let segmentSelected: UInt32 = 0xFFFFFF
        /// Dividers between regions only. Below 3:1 against every surface, so never a control border.
        public static let line: UInt32 = 0xE2E5E9
        /// Faint dividers inside a region
        public static let lineSoft: UInt32 = 0xEEF0F3
        /// Primary text on any surface
        public static let text: UInt32 = 0x111418
        /// Secondary text on any surface
        public static let textDim: UInt32 = 0x5C6570
        /// Tertiary text on bg, surface and surface-2 only, and the border of inputs and controls
        public static let textFaint: UInt32 = 0x636D77
        /// The app's accent. As text, on surface only.
        public static let accent: UInt32 = 0x2F6FE0
        /// Text and icons on an accent fill
        public static let accentInk: UInt32 = 0xFFFFFF
        /// Selected fill
        public static let accentSoft: UInt32 = 0xEAF1FD
        /// Border of a selected item
        public static let accentLine: UInt32 = 0xC5D8F7
        /// Accent text away from surface, and the hover fill of accent buttons
        public static let accentDim: UInt32 = 0x1F55B8
        /// Success. As text, on bg, surface or ok-soft.
        public static let ok: UInt32 = 0x0F7A56
        /// Success tint: ok at 10% over surface in sRGB
        public static let okSoft: UInt32 = 0xE7F2EE
        /// Decorative border for success banners, pills and toasts
        public static let okLine: UInt32 = 0xA2C0B5
        /// Warning. As text, on bg, surface or warn-soft.
        public static let warn: UInt32 = 0x8A5C00
        /// Warning tint: warn at 10% over surface in sRGB
        public static let warnSoft: UInt32 = 0xF3EFE6
        /// Decorative border for warning banners, pills and toasts
        public static let warnLine: UInt32 = 0xC4B5A1
        /// Error. As text, on bg, surface or err-soft.
        public static let err: UInt32 = 0xB42318
        /// Error tint: err at 10% over surface in sRGB
        public static let errSoft: UInt32 = 0xF8E9E8
        /// Decorative border for error banners, pills and toasts
        public static let errLine: UInt32 = 0xDAA9A3
        /// Focus outline
        public static let focusRing: UInt32 = 0x2F6FE0
        /// Backdrop behind a modal dialog or side sheet
        public static let scrim: UInt32 = 0x080A0E
        public static let scrimAlpha: Double = 0.42
        /// Dark backdrop behind a media lightbox dialog
        public static let scrimStrong: UInt32 = 0x080A0E
        public static let scrimStrongAlpha: Double = 0.78
        /// Top bar fill: bg mixed 94% with surface in OKLab, stored as a colour so that a native shell can paint its title bar with exactly the same value
        public static let topbar: UInt32 = 0xF7F7F8
    }

    public enum Dark {
        /// Page background
        public static let bg: UInt32 = 0x0E1012
        /// Panels and the primary reading surface
        public static let surface: UInt32 = 0x15181B
        /// Recessed fills such as segmented tracks and hovered rows
        public static let surface2: UInt32 = 0x1C2024
        /// Deepest fill
        public static let surface3: UInt32 = 0x252A30
        /// The selected item of a segmented control or segmented tabs, on a surface-2 track. Components read this token instead of testing the mode.
        public static let segmentSelected: UInt32 = 0x252A30
        /// Dividers between regions only. Below 3:1 against every surface, so never a control border.
        public static let line: UInt32 = 0x2A3036
        /// Faint dividers inside a region
        public static let lineSoft: UInt32 = 0x1C2024
        /// Primary text on any surface
        public static let text: UInt32 = 0xEEF1F4
        /// Secondary text on any surface
        public static let textDim: UInt32 = 0x9AA3AC
        /// Tertiary text on bg, surface and surface-2 only, and the border of inputs and controls
        public static let textFaint: UInt32 = 0x828C98
        /// The app's accent. As text, on surface only.
        public static let accent: UInt32 = 0x5A90F2
        /// Text and icons on an accent fill
        public static let accentInk: UInt32 = 0x0E1012
        /// Selected fill
        public static let accentSoft: UInt32 = 0x16263D
        /// Border of a selected item
        public static let accentLine: UInt32 = 0x2D4A72
        /// Accent text away from surface, and the hover fill of accent buttons
        public static let accentDim: UInt32 = 0x85AEF6
        /// Success. As text, on bg, surface or ok-soft.
        public static let ok: UInt32 = 0x3DBA8C
        /// Success tint: ok at 10% over surface in sRGB
        public static let okSoft: UInt32 = 0x192826
        /// Decorative border for success banners, pills and toasts
        public static let okLine: UInt32 = 0x375C52
        /// Warning. As text, on bg, surface or warn-soft.
        public static let warn: UInt32 = 0xE0A93A
        /// Warning tint: warn at 10% over surface in sRGB
        public static let warnSoft: UInt32 = 0x29271E
        /// Decorative border for warning banners, pills and toasts
        public static let warnLine: UInt32 = 0x635740
        /// Error. As text, on bg, surface or err-soft.
        public static let err: UInt32 = 0xE2725B
        /// Error tint: err at 10% over surface in sRGB
        public static let errSoft: UInt32 = 0x292121
        /// Decorative border for error banners, pills and toasts
        public static let errLine: UInt32 = 0x664844
        /// Focus outline
        public static let focusRing: UInt32 = 0x85AEF6
        /// Backdrop behind a modal dialog or side sheet
        public static let scrim: UInt32 = 0x080A0E
        public static let scrimAlpha: Double = 0.42
        /// Dark backdrop behind a media lightbox dialog
        public static let scrimStrong: UInt32 = 0x080A0E
        public static let scrimStrongAlpha: Double = 0.78
        /// Top bar fill: bg mixed 94% with surface in OKLab, stored as a colour so that a native shell can paint its title bar with exactly the same value
        public static let topbar: UInt32 = 0x0E1013
    }

    public enum Zoom {
        public static let min: Double = 0.85
        public static let defaultScale: Double = 1
        public static let max: Double = 1.5
        public static let step: Double = 0.1

        public static func clamped(_ scale: Double) -> Double {
            guard scale.isFinite else { return defaultScale }
            let bounded = Swift.min(max, Swift.max(min, scale))
            return (bounded * 100).rounded() / 100
        }

        public static func stepped(_ scale: Double, steps: Int) -> Double {
            clamped(clamped(scale) + Double(steps) * step)
        }
    }

    /// Splits 0xRRGGBB into sRGB components between 0 and 1, for example for
    /// NSColor(srgbRed:green:blue:alpha:).
    public static func components(_ hex: UInt32) -> (red: Double, green: Double, blue: Double) {
        (
            red: Double((hex >> 16) & 0xFF) / 255,
            green: Double((hex >> 8) & 0xFF) / 255,
            blue: Double(hex & 0xFF) / 255
        )
    }
}
